import React, { Component } from "react";
import { Card, CardBody, CardHeader, Col, Row, Alert, CardGroup, Button } from "reactstrap";
import { connect } from "react-redux";
import { bindActionCreators } from "redux";
import Pagination2 from "react-js-pagination";
import Widget04 from "../../../Utils/Widgets04";

import {
	fetchInterAffiliateSummaryTransactions,
	downloadInterAffiliateSummaryTransactions,
} from "../../../actions/filesets";

import { FormattedMessage } from "react-intl";
import {
	Grid,
	Table,
	TableHeaderRow,
	ColumnChooser,
	TableColumnVisibility,
	Toolbar,
} from "@devexpress/dx-react-grid-material-ui";

// import AddFileSet from './addFileSet';
// import UpdateFileSet from './updateFileSet';

class InterAffiliateIssuerSummaryTransactions extends Component {
	constructor (props) {
		super(props);
		this.state = {
			modal               : false,
			showUpdateModal     : false,
			fileSetCreatedAlert : true,
			filesetUpdatedAlert : true,
			fileSetDeletedAlert : true,
			deleteModal         : false,
			activePage          : 1,
		};
	}
	id = "";
	fileDefinitionId = "";
	componentWillMount () {
		this.props.fetchInterAffiliateSummaryTransactions(this.props.match.params.date, 0);
	}

	onSubmit = (values) => {
		this.props.createFileSet(values);
		this.setState({
			modal : false,
		});
	};

	onSubmitUpdate = (values) => {
		this.props.updateFileSet(this.id, values);
		this.closeUpdateModal();
	};

	setUpProduct = (id) => {
		this.props.history.push(`/processors/${id}/subgroups/addProduct`);
	};

	toggle = () => {
		this.props.history.push(`/filesets/${this.props.match.params.id}/definitions/add`);
	};
	closeModal = () => {
		this.setState({ modal: false });
	};
	componentWillUnmount () {
		// this.props.subGroupCreated.subGroupCreated = null;
		// this.props.subGroupCreated.createSubGroupError = null;
		// this.props.subGroupCreated.updatedSubGroup = null;
	}

	updateSubGroup = (id) => {
		this.clearNotifications();
		this.setState({ showUpdateModal: !this.state.showUpdateModal });
		this.id = id;
		this.props.fetchFileSet(id);
	};

	closeUpdateModal = () => {
		this.setState({ showUpdateModal: !this.state.showUpdateModal });
	};

	toggleUpdate = () => {
		this.setState({ showUpdateModal: !this.state.showUpdateModal });
	};

	clearNotifications = () => {
		this.props.fileSets.fileSetCreated = null;
		// this.props.subGroupCreated.createSubGroupError = null;
		// this.props.subGroupCreated.subGroupCreated = null;
	};

	onDismissFileSetCreatedSuccessAlert = () => {
		this.setState({
			fileSetCreatedAlert : false,
		});
	};

	onDismissFileSetUpdatedSuccessAlert = () => {
		this.setState({
			fileSetUpdatedAlert : false,
		});
	};

	deleteFileDefinition = (id) => {
		this.clearNotifications();
		this.setState({ deleteModal: true });
		this.fileDefinitionId = id;
	};

	toggleConfirm = () => {
		this.setState({ deleteModal: !this.state.deleteModal });
	};
	confirm = () => {
		this.props.deleteFileSetDefinition(this.props.match.params.id, this.fileDefinitionId);
		this.setState({ deleteModal: false });
	};

	onDismissFileSetDeletedSuccessAlert = () => {
		this.setState({
			fileSetDeletedAlert : false,
		});
	};

	handlePageChange = (pageNumber) => {
		let pageNumberParam = pageNumber - 1;
		this.props.fetchInterAffiliateSummaryTransactions(this.props.match.params.date, pageNumberParam);

		this.setState({ activePage: pageNumber });
	};

	downloadInterAffiliateTransactions = (date) => {
		this.props.downloadInterAffiliateSummaryTransactions(date);
	};

	onSubmit = (values) => {
		this.props.fetchFileSetsDefinitionBatchesTransactionsPaginated(
			this.props.match.params.filesetId,
			this.props.match.params.batchesId,
			this.props.match.params.definitionId,
			0,
			values.affiliate.value,
		);
	};
	render () {
		if (this.props.fileSets.interAffiliateSummaryTransactions) {
			if (this.props.fileSets.interAffiliateSummaryTransactions.data.content.length > 0) {
				delete this.props.fileSets.interAffiliateSummaryTransactions.data.content[0].interAffSummary;
				delete this.props.fileSets.interAffiliateSummaryTransactions.data.content[0].id;
				var columnHeaders = this.props.fileSets.interAffiliateSummaryTransactions.data.content[0];
				var newRows = [];
				for (var name in columnHeaders) {
					var newObj = {};
					newObj.name = name;
					newObj.title = name;
					newRows.push(newObj);
				}
				var payloadArray = [];
				this.props.fileSets.interAffiliateSummaryTransactions.data.content.forEach(function (item) {
					if (item.interAffSummary) {
						delete item.interAffSummary;
					}
					delete item.id;
					payloadArray.push(item);
				});
				//   console.log('PayloadArray is ',payloadArray);
			}
		}
		const { defaultHiddenColumnNames } = this.state;

		console.log("Props is ", this.props);
		return (
			<div className='animated fadeIn'>
				<Row>
					<Col>
						{this.props.fileSets.interAffiliateSummaryTransactions ? (
							<CardGroup className='mb-4'>
								<Widget04
									icon='icon-people'
									color='info'
									header={this.props.fileSets.interAffiliateSummaryTransactions.data.totalElements.toLocaleString()}
									value='25'
								>
									Transactions
								</Widget04>
								<Widget04 icon='icon-user-follow' color='success' header='0' value='25'>
									Successful Transactions
								</Widget04>
								<Widget04 icon='icon-basket-loaded' color='warning' header='0' value='25'>
									Credits
								</Widget04>
								<Widget04 icon='icon-pie-chart' color='primary' header='0' value='5'>
									Debits
								</Widget04>
								<Widget04 icon='icon-speedometer' color='danger' header='0' value='25'>
									Amount
								</Widget04>
							</CardGroup>
						) : null}
					</Col>
				</Row>
				<Row>
					<Col lg={12}>
						{this.props.fileSets.fileSetFileDefinitionDeleted ? (
							<Alert
								color='success'
								isOpen={this.state.fileSetDeletedAlert}
								toggle={this.onDismissFileSetDeletedSuccessAlert}
							>
								<FormattedMessage
									id='Success: FileSet Deleted Succesfully!'
									defaultMessage='Success: FileSet Deleted Succesfully!'
								/>
							</Alert>
						) : null}
						<Card>
							<CardHeader>
								<strong>
									{" "}
									{this.props.fileSets.interAffiliateSummaryTransactions ? (
										<React.Fragment>
											Inter Affilaite {this.props.match.params.date} Summary
										</React.Fragment>
									) : (
										""
									)}
									<FormattedMessage id=' Transactions' defaultMessage=' Transactions' />
								</strong>
								{this.props.fileSets.interAffiliateSummaryTransactions ? (
									[
										this.props.fileSets.interAffiliateSummaryTransactions.data.content.length >
										0 ? (
											<Button
												className={"float-right mb-0 btn-sm"}
												color='success'
												onClick={(e) =>
													this.downloadInterAffiliateTransactions(
														this.props.match.params.date,
													)}
											>
												<i className='fa fa-download' />&nbsp;{" "}
												<FormattedMessage id='Download CSV' defaultMessage='Download CSV' />
											</Button>
										) : (
											""
										),
									]
								) : (
									[ "" ]
								)}
							</CardHeader>
							<CardBody>
								{this.props.fileSets.interAffiliateSummaryTransactions ? (
									[
										this.props.fileSets.interAffiliateSummaryTransactions.data.content.length >
										0 ? this.props.fileSets.interAffiliateSummaryTransactions ? (
											<Grid rows={payloadArray} columns={newRows}>
												<Table />
												<TableHeaderRow />
												<TableColumnVisibility
													defaultHiddenColumnNames={defaultHiddenColumnNames}
												/>
												<Toolbar />
												<ColumnChooser />
											</Grid>
										) : (
											<p className='text-center text-danger'>
												<FormattedMessage
													id='There are no batch transactions at the moment.'
													defaultMessage='There are no batch transactions at the moment.'
												/>
											</p>
										) : (
											<p className='text-center text-danger'>
												<FormattedMessage
													id='There are no batch transactions at the moment.'
													defaultMessage='There are no batch transactions at the moment.'
												/>
											</p>
										),
									]
								) : (
									[ "" ]
								)}
								{this.props.fileSets.interAffiliateSummaryTransactions ? (
									<nav>
										<Pagination2
											activePage={this.state.activePage}
											itemsCountPerPage={20}
											totalItemsCount={
												this.props.fileSets.interAffiliateSummaryTransactions ? (
													this.props.fileSets.interAffiliateSummaryTransactions.data
														.totalElements
												) : null
											}
											pageRangeDisplayed={5}
											onChange={this.handlePageChange}
										/>
									</nav>
								) : (
									""
								)}
							</CardBody>
						</Card>
					</Col>
				</Row>
			</div>
		);
	}
}

const mapStateToProps = (state) => {
	console.log("State is ", state);
	return {
		fileSets : state.fileSets,
		utils    : state.utils,
	};
};

const mapDispatchToProps = (dispatch) => {
	return bindActionCreators(
		{
			fetchInterAffiliateSummaryTransactions,
			downloadInterAffiliateSummaryTransactions,
		},
		dispatch,
	);
};

export default connect(mapStateToProps, mapDispatchToProps)(InterAffiliateIssuerSummaryTransactions);
